sequence.script:
var payload = mc.getPayloadJSON();
var validationError = "";

if (!payload || !payload.header || !payload.spk_list) {
    validationError = "Missing required 'header' or 'spk_list' in request payload";
} else {
    var h = payload.header;
    var spkList = payload.spk_list;

    // 1. Validasi Jumlah SPK (1 s/d 50 SPK)
    if (!Array.isArray(spkList) || spkList.length < 1 || spkList.length > 50) {
        validationError = "spk_list must contain between 1 and 50 SPKs";
    }

    // 2. Validasi Format Tanggal YYYY-MM-DD
    var dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!validationError) {
        if (!h.invoice_date || !dateRegex.test(String(h.invoice_date).trim()) || 
            !h.tax_invoice_date || !dateRegex.test(String(h.tax_invoice_date).trim())) {
            validationError = "Invalid date format, expected YYYY-MM-DD";
        }
    }

    // 3. Validasi Format Faktur Pajak 16 Digit: XXX.XXX-XX.XXXXXXXX
    var taxInvoiceRegex = /^\d{3}\.\d{3}-\d{2}\.\d{8}$/;
    if (!validationError) {
        if (!h.tax_invoice_number || !taxInvoiceRegex.test(String(h.tax_invoice_number).trim())) {
            validationError = "Invalid tax_invoice_number format";
        }
    }

    // 4. Validasi Perhitungan Matematika & Mapping G/L
    var sumSpkSubtotal = 0;
    var sumSpkTax = 0;

    if (!validationError) {
        for (var s = 0; s < spkList.length; s++) {
            var spk = spkList[s];
            if (!spk) {
                validationError = "Invalid SPK object at index " + s;
                break;
            }

            var spkSubtotal = Number(spk.spk_subtotal);
            var spkTax = Number(spk.spk_tax_amount);
            var spkGrandTotal = Number(spk.spk_grand_total);

            if (isNaN(spkSubtotal) || isNaN(spkTax) || isNaN(spkGrandTotal)) {
                validationError = "Invalid numerical values in SPK " + (spk.spk_number || s);
                break;
            }

            sumSpkSubtotal += spkSubtotal;
            sumSpkTax += spkTax;

            // Setiap SPK wajib memiliki minimal 1 item
            if (!Array.isArray(spk.items) || spk.items.length === 0) {
                validationError = "SPK subtotal does not match sum of item amounts";
                break;
            }

            var sumItemAmount = 0;
            for (var it = 0; it < spk.items.length; it++) {
                var item = spk.items[it];
                if (!item) {
                    validationError = "Invalid item in SPK " + (spk.spk_number || s);
                    break;
                }
                var qty = Number(item.qty);
                var unitPrice = Number(item.unit_price);
                var totalAmount = Number(item.total_amount);

                if (isNaN(qty) || isNaN(unitPrice) || isNaN(totalAmount) || Math.abs((qty * unitPrice) - totalAmount) > 0.000001) {
                    validationError = "Item total_amount must equal qty * unit_price";
                    break;
                }

                sumItemAmount += totalAmount;

                // Otomasi Mapping G/L Account SAP (Bab 4.2)
                var comp = String(item.component || "").trim().toLowerCase();
                if (comp === "jasa") {
                    item.gl_number = "5000000007";
                } else if (comp === "part") {
                    item.gl_number = "5000000008";
                } else {
                    item.gl_number = item.gl_number || "5000000007";
                }
            }

            if (validationError) break;

            if (Math.abs(sumItemAmount - spkSubtotal) > 0.000001) {
                validationError = "SPK subtotal does not match sum of item amounts";
                break;
            }
        }
    }

    // Validasi Korelasi Header Subtotal, Tax, dan Grand Total
    if (!validationError) {
        var totalSubtotal = Number(h.total_subtotal_amount);
        var totalTax = Number(h.total_tax_amount);
        var totalInvoice = Number(h.total_invoice_amount);

        if (Math.abs(sumSpkSubtotal - totalSubtotal) > 0.000001) {
            validationError = "total_subtotal_amount does not match sum of SPK subtotals";
        } else if (Math.abs(sumSpkTax - totalTax) > 0.000001) {
            validationError = "total_tax_amount does not match sum of SPK tax amounts";
        } else if (Math.abs((totalSubtotal + totalTax) - totalInvoice) > 0.000001) {
            validationError = "total_invoice_amount does not match subtotal + tax amount";
        }
    }

    // Jika valid, generate dokumen XML target <INVOICE_INBOUND_REQUEST>
    if (!validationError) {
        function esc(v) {
            if (v === null || v === undefined) return "";
            return String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
        }

        var xml = '<?xml version="1.0" encoding="UTF-8"?>\n<INVOICE_INBOUND_REQUEST>\n';
        xml += '  <HEADER>\n';
        xml += '    <BILLING_NUMBER>' + esc(h.billing_number) + '</BILLING_NUMBER>\n';
        xml += '    <INVOICE_NUMBER>' + esc(h.invoice_number) + '</INVOICE_NUMBER>\n';
        xml += '    <INVOICE_DATE>' + esc(h.invoice_date) + '</INVOICE_DATE>\n';
        xml += '    <INVOICE_TYPE>' + esc(h.invoice_type || 'spk') + '</INVOICE_TYPE>\n';
        xml += '    <MEMO>' + esc(h.memo || '') + '</MEMO>\n';
        xml += '    <VENDOR_CODE>' + esc(h.vendor_code) + '</VENDOR_CODE>\n';
        xml += '    <VENDOR_NAME>' + esc(h.vendor_name) + '</VENDOR_NAME>\n';
        xml += '    <COMPANY_CODE>' + esc(h.company_code || '1000') + '</COMPANY_CODE>\n';
        xml += '    <TENANT_ID>' + esc(h.tenant_id) + '</TENANT_ID>\n';
        xml += '    <TAX_INVOICE_NUMBER>' + esc(h.tax_invoice_number) + '</TAX_INVOICE_NUMBER>\n';
        xml += '    <TAX_INVOICE_DATE>' + esc(h.tax_invoice_date) + '</TAX_INVOICE_DATE>\n';
        xml += '    <CURRENCY>' + esc(h.currency || 'IDR') + '</CURRENCY>\n';
        xml += '    <TOTAL_SUBTOTAL_AMOUNT>' + Math.round(Number(h.total_subtotal_amount)) + '</TOTAL_SUBTOTAL_AMOUNT>\n';
        xml += '    <TOTAL_TAX_AMOUNT>' + Math.round(Number(h.total_tax_amount)) + '</TOTAL_TAX_AMOUNT>\n';
        xml += '    <TOTAL_INVOICE_AMOUNT>' + Math.round(Number(h.total_invoice_amount)) + '</TOTAL_INVOICE_AMOUNT>\n';
        xml += '  </HEADER>\n';
        xml += '  <SPK_LIST>\n';
        for (var s = 0; s < spkList.length; s++) {
            var spkObj = spkList[s];
            xml += '    <SPK>\n';
            xml += '      <SPK_NUMBER>' + esc(spkObj.spk_number) + '</SPK_NUMBER>\n';
            xml += '      <SR_NUMBER>' + esc(spkObj.sr_number) + '</SR_NUMBER>\n';
            xml += '      <LICENSE_PLATE>' + esc(spkObj.license_plate) + '</LICENSE_PLATE>\n';
            xml += '      <CATEGORY>' + esc(spkObj.category) + '</CATEGORY>\n';
            if (String(spkObj.category).toLowerCase() !== 'body_repair' && spkObj.sub_category) {
                xml += '      <SUB_CATEGORY>' + esc(spkObj.sub_category) + '</SUB_CATEGORY>\n';
            }
            xml += '      <SPK_SUBTOTAL>' + Math.round(Number(spkObj.spk_subtotal)) + '</SPK_SUBTOTAL>\n';
            xml += '      <SPK_TAX_AMOUNT>' + Math.round(Number(spkObj.spk_tax_amount)) + '</SPK_TAX_AMOUNT>\n';
            xml += '      <SPK_GRAND_TOTAL>' + Math.round(Number(spkObj.spk_grand_total)) + '</SPK_GRAND_TOTAL>\n';
            xml += '      <ITEMS>\n';
            for (var it = 0; it < spkObj.items.length; it++) {
                var itemObj = spkObj.items[it];
                xml += '        <ITEM>\n';
                xml += '          <ITEM_NO>' + itemObj.item_no + '</ITEM_NO>\n';
                xml += '          <COMPONENT>' + esc(itemObj.component) + '</COMPONENT>\n';
                xml += '          <GL_NUMBER>' + esc(itemObj.gl_number) + '</GL_NUMBER>\n';
                xml += '          <ITEM_NAME>' + esc(itemObj.item_name) + '</ITEM_NAME>\n';
                xml += '          <METHOD>' + esc(itemObj.method || '') + '</METHOD>\n';
                xml += '          <QTY>' + itemObj.qty + '</QTY>\n';
                xml += '          <UOM>' + esc(itemObj.uom) + '</UOM>\n';
                xml += '          <UNIT_PRICE>' + Math.round(Number(itemObj.unit_price)) + '</UNIT_PRICE>\n';
                xml += '          <TOTAL_AMOUNT>' + Math.round(Number(itemObj.total_amount)) + '</TOTAL_AMOUNT>\n';
                xml += '        </ITEM>\n';
            }
            xml += '      </ITEMS>\n';
            xml += '    </SPK>\n';
        }
        xml += '  </SPK_LIST>\n</INVOICE_INBOUND_REQUEST>';

        try {
            var om = org.apache.axiom.om.util.AXIOMUtil.stringToOM(xml);
            mc.setPayloadXML(om);
        } catch (ex) {
            mc.setPayloadXML(new XML(xml));
        }
    }
}

mc.setProperty("AP_VALIDATION_ERROR", validationError);

var billingNo = String(mc.getProperty("billingNumber") || "BIL");
var cleanBilling = billingNo.replace(/\//g, "-").replace(/\s+/g, "_");
mc.setProperty("cleanBillingNumber", cleanBilling);
